from pathlib import Path
import json,shutil
b=Path('Library/WorkshopBackups/DB-ON-103');b.mkdir(parents=True,exist_ok=True)
for src,name in [('Assets/Scenes/LobbyIslandWorkshop.unity','LobbyIslandWorkshop.before.unity'),('Assets/Igrodelnya/Localization/LocalizationData.asset','LocalizationData.before.asset')]:shutil.copy2(src,b/name)
prefix=Path('tools/assets/Market100.cs.txt').read_text(encoding='utf-8-sig').split(' public static string Run()')[0].replace('class Market100','class Inspect103')
code=prefix+r''' public static string Run(){var root=GameObject.Find("Lobby_Island_Visual_Prototype").transform;if(Application.dataPath!="E:/Fork/dead_boat/Assets")throw new Exception("Wrong project");var harbour=root.Find("04_Boat_Skins_Showcase/Boat_Harbour_CentralPier102");foreach(string n in new[]{"Actual_Boat_RenderOnly_1to1","Actual_Castle_Wooden_Boat_Static100"}){var t=harbour.Find(n);var v=V(t).Select(t.InverseTransformPoint).ToArray();report.AppendLine(n+" rootpos="+t.localPosition+" bounds local min="+new Vector3(v.Min(q=>q.x),v.Min(q=>q.y),v.Min(q=>q.z))+" max="+new Vector3(v.Max(q=>q.x),v.Max(q=>q.y),v.Max(q=>q.z)));foreach(var q in t.GetComponentsInChildren<Transform>(true))if(q.name=="Point"||q.name=="Fire"||q.name=="steering"||q.name.Contains("Coal")||q.name.Contains("Fire")||q.name.Contains("steer")||q.name.Contains("furnace")||q.name.Contains("furnace"))report.AppendLine("CONTROL "+q.name+" parent="+q.parent.name+" root="+t.InverseTransformPoint(q.position)+" rot="+q.localEulerAngles+" active="+q.gameObject.activeInHierarchy+" mesh="+q.GetComponentsInChildren<MeshFilter>(true).Length);foreach(Transform q in t)report.AppendLine("CHILD "+q.name+" pos="+q.localPosition);}
var white=harbour.Find("Actual_Boat_RenderOnly_1to1");foreach(var mf in white.GetComponentsInChildren<MeshFilter>())report.AppendLine("WHITE MESH "+mf.name+" parent="+mf.transform.parent.name+" local="+white.InverseTransformPoint(mf.transform.position)+" material="+mf.GetComponent<Renderer>().sharedMaterial.name);File.WriteAllText("Library/WorkshopBackups/DB-ON-103/inspect.txt",report.ToString());return report.ToString();}}
'''
(b/'inspect.json').write_text(json.dumps({'csharpCode':code,'className':'Inspect103','methodName':'Run'}),encoding='utf-8')
